-- AEGIS SIMULATED / EXTRAPOLATED TRADING DATA
-- This data is intentionally stored separately from the real `trades` table.
-- It must not be presented as observed paper-trading performance.

CREATE TABLE IF NOT EXISTS simulated_trades (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    projection_id TEXT NOT NULL UNIQUE,
    timestamp TEXT NOT NULL,
    asset TEXT NOT NULL,
    action TEXT NOT NULL,
    side TEXT NOT NULL,
    quantity REAL NOT NULL,
    entry_price REAL NOT NULL,
    confidence REAL,
    stop_loss REAL,
    take_profit REAL,
    source_basis TEXT,
    status TEXT NOT NULL DEFAULT 'SIMULATED'
);

